<span class="line"><span style="color:#ABB2BF;">    speed </span><span style="color:#C678DD;">FLOAT</span><span style="color:#ABB2BF;">,           </span><span style="color:#7F848E;font-style:italic;">-- 速度(km/h)</span></span>
