<span class="line"><span style="color:#ABB2BF;">        rules </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> rate.surcharge_rules </span><span style="color:#C678DD;">or</span><span style="color:#ABB2BF;"> []</span></span>
